    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"
    for x in range(n // a + 1 if a != 0 else n + 1):
        remainder = n - a * x
        if remainder < 0:
            # since x is increasing, no need to continue if remainder is negative
            break
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
