def compute_Last_Digit(a: int, b: int) -> int:
    # If a > b: compute last digit of a! / b! = product of (b+1) to a
    # If a == b: result is 1 (empty product)
    # If a < b: compute last digit of product (a+1) to b

    # Define a helper to compute product last digit over a range [start+1, end]
    def product_last_digit(start, end):
        length = end - start
        if length == 0:
            return 1
        # If length >=5, product includes multiples of 5 and even numbers,
        # so last digit is 0
        if length >= 5:
            return 0
        # Else compute product modulo 10 directly
        prod = 1
        for x in range(start + 1, end + 1):
            prod = (prod * (x % 10)) % 10
        return prod

    if a > b:
        return product_last_digit(b, a)
    else:
        # a <= b
        return product_last_digit(a, b)

